#!/usr/bin/env python3
"""Rebuild the editable dictionary and HTML from authoritative Flyway migrations.
Run: python3 docs/database/generate.py && node docs/database/render.mjs
Dependencies: existing docs/build/node_modules (Playwright + Archivo + Poppins), Graphviz.
"""
from pathlib import Path
import re, html, json, subprocess
ROOT=Path(__file__).resolve().parents[2]; OUT=ROOT/'docs/database'
E=lambda x: html.escape(str(x))
from schema import tables, fks, checks, uniques, indexes
verification=json.loads((ROOT/'docs/evidence/verification.json').read_text())
unit=verification['surefire']['totals']['tests']; integration=verification['failsafe']['totals']['tests']; frontend=verification['frontend']; newman=verification['newman']
(OUT/'schema.json').write_text(json.dumps(dict(tables=tables,foreign_keys=fks,indexes=indexes),indent=2)+'\n')
# A focused ER overview: field-level constraints remain legible in table sheets.
dot=['digraph ER { graph [rankdir=TB,bgcolor="transparent",pad="0.2",nodesep="0.65",ranksep="0.9"]; node [shape=box,style="rounded,filled",fillcolor="#f4edde",color="#315c91",fontname="DejaVu Sans",fontsize=15,margin="0.18"]; edge [color="#315c91",fontname="DejaVu Sans",fontsize=13,arrowsize=0.6];']
for t in tables: dot.append(f'{t["name"]} [label="{t["name"]}\\n{len(t["columns"])} columns"];')
for f in fks:
 # creator links share a clearly documented dedicated matrix; all 13 still drawn.
 dot.append(f'{f["parent"]} -> {f["child"]} [label="{f["col"]}\\n{("0..1" if f["optional"] else "1")} : 0..*",style={"dashed" if f["optional"] else "solid"}];')
dot.append('}')
(OUT/'relationships.dot').write_text('\n'.join(dot))
subprocess.run(['dot','-Tsvg',str(OUT/'relationships.dot'),'-o',str(OUT/'relationships.svg')],check=True)

def table(headers,rows,cls=''):
 return '<table class="'+cls+'"><thead><tr>'+''.join('<th>'+E(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+E(c)+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table>'
def box(title,text): return f'<aside><b>{E(title)}</b><p>{E(text)}</p></aside>'
pages=[]
def page(title,sub,body,cls=''):
 n=len(pages)+1
 pages.append(f'<section class="page {cls}"><div class="bars"><i></i><i></i><i></i><i></i><i></i><i></i></div><header>SMARTSOFT SOLUTIONS <span>ATELIER / DATABASE REFERENCE</span></header><div class="eyebrow">{E(sub)}</div><h1>{E(title)}</h1>{body}<footer><span>18 NOV 2026 · FLYWAY V1 + V2 + V3</span><b>{n:02}</b></footer></section>')
count=sum(len(t['columns']) for t in tables)
page('A database built\nfor the atelier.','Technical reference / 2026',f'<p class="deck">Complete schema dictionary, relationships and integrity rules for the Spring Boot + Angular art gallery.</p><div class="metrics"><div><b>8</b><span>application tables</span></div><div><b>{count}</b><span>stored columns</span></div><div><b>13</b><span>foreign keys</span></div></div><div class="cover-mark">A<span>•</span></div><div class="cover-note"><b>Authoritative foundation</b><p>Flyway migrations define the physical database. JPA mappings explain object navigation. Service rules are identified separately so they cannot be mistaken for SQL constraints.</p></div>','cover')
page('The schema at a glance','01 / Structure', '<p>Eight application tables in MySQL / InnoDB. Flyway also maintains its own migration-history table; that infrastructure table is outside this application dictionary.</p><div class="graph"><img src="relationships.svg"></div>'+box('How to read the graph','Arrows run from referenced parent to referencing child. Labels show parent per child : children per parent. Dashed links are nullable; solid links are mandatory. All parent records may have zero children.')+'<p class="small">Every foreign key appears here. The complete names, optional links and deletion actions are tabulated on page 12. The full editable SVG accompanies this document.</p>')
page('The required relationships','02 / CDC and JPA','<h2>User ↔ Role: many-to-many</h2><p><code>user_roles</code> joins each user to any number of roles and each role to any number of users. Its composite primary key prevents duplicate assignments. <code>User.roles</code> is mapped with <code>@ManyToMany</code>.</p>'+box('Minimum participation is an application rule','The CDC asks for one or more roles. Validated user DTOs use @ValidRoleSelection and services assign roles. SQL alone allows a user with zero user_roles rows.')+'<h2>Artist → Exhibition: one-to-many</h2><p>The CDC Client maps to Artist; Projet maps to Exhibition. <code>Artist.exhibitions</code> uses <code>@OneToMany(mappedBy="artist")</code>. <code>Exhibition.artist</code> uses <code>@ManyToOne(optional=false)</code>; its SQL foreign key is NOT NULL.</p><p>An artist may initially have no exhibition, then many. Each exhibition has exactly one artist. The CDC wording does not require a newly created artist to already have a project.</p>'+box('There is no one-to-one relationship','No one-to-one relation is required by the supplied CDC or present in the schema. auctions.artwork_id is not unique: an artwork may have multiple historical auctions. A service rule limits live overlap.')+'<h2>Persistence proof</h2><p><code>DatabaseRelationshipsIT</code> flushes and clears the persistence context, then verifies shared roles, several roles per user, and two exhibitions for one artist through both JPA navigation directions.</p>')
notes={
'roles':('Role catalogue','Editable unique labels are independent from permission profiles ADMIN, COLLABORATEUR and BIDDER. profile is NOT NULL. Nullable unique system_key identifies required roles independently of renamed labels. Multiple custom roles may have NULL system_key. SQL has no CHECK limiting profile membership. ADMIN role CRUD preserves system profiles and blocks deletion or profile changes for assigned custom roles.'),
'users':('Accounts and identity','password stores a BCrypt hash, never plaintext. email uniqueness is declared by SQL; case handling depends on database collation and service normalization. SQL does not require a user_roles row. No version column is present on users.'),
'user_roles':('Many-to-many association','No surrogate id and no JPA entity are needed. The composite primary key makes each pair unique. A user deletion cascades to assignments; a referenced role cannot be deleted. Application user-deletion safeguards can be stricter than these SQL actions.'),
'artists':('CDC Client equivalent','created_by_id is optional audit attribution, not ownership. Deleting the author via direct SQL nulls the reference. Artist email is not unique. version supports JPA optimistic locking. The inverse exhibitions collection creates no extra column.'),
'exhibitions':('CDC Projet equivalent','artist_id is required. Referenced artists cannot be deleted while exhibitions remain. Deleting a creator nulls the audit link. budget >= 0 and duration_days > 0 are SQL CHECK constraints. All other optional fields may be NULL.'),
'artworks':('Gallery catalogue extension','artist_id is required and exhibition_id is optional. Deleting an exhibition clears exhibition_id. The service checks that the exhibition and artwork belong to the same artist; no composite FK enforces this across tables. SQL does not CHECK status, estimate or year ranges.'),
'auctions':('Timed auction extension','An artwork may have several auctions over time; artwork_id is indexed, not unique. Leader and winner are independently nullable user references. No SQL constraint requires them to match a bid. Status values, bid-count consistency and live-auction overlap are controlled by application logic.'),
'bids':('Accepted bid ledger','Each bid belongs to exactly one auction and one bidder. An auction deletion cascades to bids in SQL, while the application refuses to delete auctions that already have bids. A bidder with retained bids cannot be deleted. created_at has no SQL default and must be supplied.')}
for t in tables:
 title,desc=notes[t['name']]
 rows=[[c['name'],c['type'],'YES' if c['nullable'] else 'NO',c['default'],c['key']] for c in t['columns']]
 body=f'<p class="deck compact">{E(title)}</p>'+table(['Column','SQL type','NULL','Default / identity','Key'],rows,'dictionary')
 body+='<h2>Keys and table constraints</h2><pre>'+E('PRIMARY KEY ('+', '.join(t['pk'])+')\n'+'\n'.join(c for c in t['constraints'] if not c.startswith('PRIMARY KEY')))+'</pre>'
 relevant=[i for i in indexes if i['table']==t['name']]
 body+='<p class="small"><b>Explicit secondary indexes:</b> '+E('; '.join(i['name']+' ('+i['columns']+')' for i in relevant) or 'None. PK, unique and FK supporting indexes are described on page 14.')+'</p>'
 body+=box('Interpretation',desc)
 page(t['name'],'03 / Table dictionary',body)
rows=[[f['name'],f['child']+'.'+f['col'],f['parent']+'.'+f['pcol'],'0..1' if f['optional'] else '1',f['delete']] for f in fks]
page('All 13 foreign keys','04 / Cardinalities and deletion',table(['Constraint','Referencing column','Parent','Parent / child','ON DELETE'],rows,'relationships')+'<p>For every row above, a parent can have <b>0..many</b> children. A mandatory FK means each child needs one parent, not that every parent needs a child.</p>'+box('Deletion summary','2 CASCADE links remove child rows; 4 SET NULL links retain rows and clear references; 7 unspecified ON DELETE clauses use MySQL RESTRICT / NO ACTION behavior. No FK specifies ON UPDATE, so parent-key changes use the default restrictive action.')+'<p class="small">CASCADE: users → user_roles; auctions → bids. SET NULL: users → artists / exhibitions / artworks (creator); exhibitions → artworks. Other links restrict deletion while references exist.</p>')
page('Integrity: where it lives','05 / Constraint inventory','<h2>Primary and unique keys</h2><p>All eight tables have a primary key. Seven use a BIGINT AUTO_INCREMENT id; user_roles uses (user_id, role_id). Five named unique constraints complement them.</p>'+table(['Table','Unique constraint'],uniques,'inventory')+ '<h2>Four SQL CHECK constraints</h2>'+table(['Table','Expression'],[(t,s) for t,s in checks],'inventory')+box('No hidden SQL guarantees','There is no SQL CHECK for enum membership, positive bid amounts, nonnegative estimates, bid_count, minimum role count or artwork/exhibition artist consistency. There is no UNIQUE on auctions.artwork_id or on artists.email.')+'<h2>Application integrity</h2><p>DTO validation and service methods enforce form validation, authorizations, role assignment, artist/exhibition consistency, auction transitions and bid increments. Auction bidding uses pessimistic row locking; version columns on catalogue records and auctions support optimistic locking.</p>')
# Derive predictable InnoDB supporting indexes, but explicitly identify as inferred.
implicit=[]
for f in fks:
 t=next(t for t in tables if t['name']==f['child'])
 covered=(t['pk'] and t['pk'][0]==f['col']) or any(i['table']==t['name'] and i['columns'].split(',')[0].strip()==f['col'] for i in indexes) or any(tt==t['name'] and re.search(r'UNIQUE \('+f['col']+r'(?:,|\))',s) for tt,s in uniques)
 if not covered: implicit.append([f['child'],f['col'],f['name']])
page('Indexes and storage','06 / Access paths','<h2>Five explicit CREATE INDEX statements</h2>'+table(['Index','Table','Ordered columns'],[(i['name'],i['table'],i['columns']) for i in indexes])+'<h2>Primary / unique indexes</h2><p>InnoDB creates an index for each primary key and each unique constraint. The leftmost prefix of user_roles(user_id, role_id) supports its user FK; uk_bids_auction_amount(auction_id, amount) supports its auction FK. idx_bids_bidder supports bidder_id; idx_auctions_artwork supports artwork_id.</p><h2>Additional FK supporting indexes</h2><p class="small">InnoDB creates supporting indexes when no suitable index already exists. Below are expected names from a fresh migration, inferred from the DDL; inspect SHOW INDEX for actual runtime names if the schema has evolved.</p>'+table(['Table','Leading column','Expected FK index name'],implicit,'relationships')+box('Type and default conventions','BOOLEAN is MySQL’s TINYINT(1) alias. A nullable column without an explicit default accepts NULL. A required column marked “-” has no explicit SQL default. TIMESTAMP(6) stores microsecond precision. No migration declares charset or collation; database defaults apply.'))
page('Evidence and regeneration','07 / Verification and maintenance','<h2>Source order</h2><ol><li><b>Physical schema:</b> backend/src/main/resources/db/migration/V1__core_schema.sql, V2__artworks_auctions_bids.sql and V3__dynamic_roles.sql.</li><li><b>Object mappings:</b> User, Role, Artist, Exhibition, Artwork, Auction, Bid and AuditedEntity.</li><li><b>Business rules:</b> user, artwork and auction services plus validated request DTOs.</li></ol><h2>Verified evidence / 18 November 2026</h2>'+table(['Evidence','Result'],[['Backend unit tests',f'{unit} passed; no failures or skips'],['MySQL integration tests',f'{integration} passed; no failures or skips'],['Relationship persistence tests','2 DatabaseRelationshipsIT cases included above'],['Frontend tests',f'{frontend["tests"]} passed across {frontend["files"]} files'],['Postman / Newman',f'{newman["requests"]["total"]} requests; {newman["assertions"]["total"]} assertions; zero failures'],['Production container','Java 17 image with Angular in psm.jar; locally exercised'],['Remote VPS','Pending: no live VPS evidence']])+box('Evidence boundary','Counts come from docs/evidence/verification.json. A passing local production container is evidence for CDC step 11, not proof of deployment to a remote VPS (step 12). This document does not claim complete CDC compliance.')+'<h2>Rebuild from the repository root</h2><pre>python3 docs/database/generate.py\nnode docs/database/render.mjs</pre><p class="small">Editable HTML: docs/database/database.html. Generator: generate.py. Print renderer: render.mjs. Supporting artifacts: schema.json and relationships.dot / .svg. The generator also refreshes docs/DATABASE.md.</p>')
css='''@font-face{font-family:Archivo;src:url('../build/node_modules/@fontsource-variable/archivo/files/archivo-latin-wght-normal.woff2')}@font-face{font-family:Poppins;src:url('../build/node_modules/@fontsource/poppins/files/poppins-latin-400-normal.woff2');font-weight:400}@font-face{font-family:Poppins;src:url('../build/node_modules/@fontsource/poppins/files/poppins-latin-600-normal.woff2');font-weight:600}:root{--midnight:#101d35;--cobalt:#315c91;--sunflower:#e7b84b;--ivory:#f4edde}*{box-sizing:border-box}html{print-color-adjust:exact;-webkit-print-color-adjust:exact}body{margin:0;background:#d9dee5;color:var(--midnight);font-family:Poppins,sans-serif}.page{width:210mm;height:297mm;position:relative;margin:7mm auto;padding:23mm 17mm 18mm;background:white;overflow:hidden;break-after:page}.bars{height:5mm;display:flex;position:absolute;top:0;left:0;right:0}.bars i{flex:1;background:var(--midnight)}.bars i:nth-child(even){background:var(--sunflower)}header{font-size:7px;letter-spacing:1px;position:absolute;top:12mm;left:17mm;right:17mm;font-weight:600}header span{float:right;color:var(--cobalt)}.eyebrow{font-size:9px;text-transform:uppercase;letter-spacing:2.6px;color:var(--cobalt);margin:5mm 0 3mm}h1{font-family:Archivo,sans-serif;font-size:36px;line-height:1.05;margin:0 0 6mm;white-space:pre-line;font-weight:800;letter-spacing:-.8px}h2{font-family:Archivo,sans-serif;font-size:17px;margin:5mm 0 2mm;color:var(--cobalt)}p,li{font-size:12px;line-height:1.6}p{margin:0 0 3mm}ol{padding-left:5mm}.deck{font-size:15px;line-height:1.6;max-width:145mm}.compact{font-size:14px;margin-top:-2mm}table{width:100%;border-collapse:collapse;font-size:10.5px;margin:3mm 0 4mm}th{background:var(--midnight);color:white;text-align:left;font-size:9px;letter-spacing:.2px;padding:2.3mm 1.7mm}td{padding:2.2mm 1.7mm;border-bottom:1px solid #d7dce4;vertical-align:top;overflow-wrap:anywhere}tr:nth-child(even) td{background:#f3f5f8}.inventory th:first-child{width:18%}.inventory td:first-child{white-space:nowrap}.dictionary td:first-child{font-weight:600}.dictionary td{padding:1.7mm 1.5mm}.dictionary td:nth-child(2){white-space:nowrap}.relationships{font-size:9px}.relationships td{padding:2.1mm 1.2mm}.relationships th{font-size:8px}aside{background:var(--ivory);border-left:4px solid var(--sunflower);padding:3mm 4mm;margin:4mm 0}aside b{font-size:10px}aside p{font-size:11px;margin:1.5mm 0 0}pre{font-family:monospace;font-size:9px;line-height:1.5;background:#f3f5f8;padding:3mm;white-space:pre-wrap;overflow-wrap:anywhere;margin:2mm 0 3mm}code{font-size:.94em;background:var(--ivory);padding:0 2px}.small{font-size:10px;line-height:1.6}footer{position:absolute;left:17mm;right:17mm;bottom:10mm;border-top:1px solid #b9c5d5;padding-top:3mm;font-size:7px;letter-spacing:1px;color:var(--cobalt)}footer b{float:right;font-size:11px}.graph{height:130mm;display:flex;align-items:center;margin:4mm -7mm}.graph img{width:100%;max-height:100%;object-fit:contain}.cover{background:var(--ivory)}.cover h1{font-size:57px;max-width:170mm;margin-top:8mm}.cover .deck{max-width:143mm}.metrics{display:flex;gap:12mm;margin-top:10mm}.metrics div{display:flex;flex-direction:column}.metrics b{font-family:Archivo;font-size:42px;color:var(--cobalt)}.metrics span{font-size:9px}.cover-mark{font-family:Archivo;font-weight:800;position:absolute;top:155mm;right:15mm;font-size:180px;line-height:1;color:var(--midnight);letter-spacing:-20px}.cover-mark span{color:var(--sunflower)}.cover-note{position:absolute;bottom:30mm;width:132mm;border-top:3px solid var(--cobalt);padding-top:5mm}.cover-note b{font-size:11px}.cover-note p{font-size:10px;margin-top:2mm}@page{size:A4;margin:0}@media print{body{background:white}.page{margin:0}}'''
(OUT/'database.css').write_text(css)
(OUT/'database.html').write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><title>ATELIER - Database Reference</title><link rel="stylesheet" href="database.css"></head><body>'+''.join(pages)+'</body></html>')
md=['# Database schema and cardinalities','', 'Generated from Flyway V1, V2 and V3 by `python3 docs/database/generate.py`. SQL is authoritative. Full printable reference: [database.pdf](database.pdf); editable source: [database/database.html](database/database.html).','', '![All 13 database relationships](database/relationships.svg)','', '## Required CDC relationships','', '- **User–Role: many-to-many** through `user_roles`; `User.roles` uses `@ManyToMany`. Composite PK prevents duplicate assignments. DTO/service rules require at least one role; SQL alone permits zero assignments.','- **Client–Projet: one-to-many / many-to-one**, adapted as Artist–Exhibition. `Artist.exhibitions` is `@OneToMany(mappedBy="artist")`; `Exhibition.artist` is `@ManyToOne(optional=false)`. Artist has 0..many exhibitions; each exhibition has exactly 1 artist.','- **No one-to-one** is required or present. An artwork has 0..many historical auctions; live overlap is restricted by the service, not a UNIQUE constraint.','', 'Persistence proof: `DatabaseRelationshipsIT` flushes/clears then reloads both required relationships.','', '## All foreign keys','', '| Constraint | Child column | Parent | Parent per child | Children per parent | ON DELETE |','|---|---|---|---|---|---|']
for f in fks: md.append(f'| `{f["name"]}` | `{f["child"]}.{f["col"]}` | `{f["parent"]}.{f["pcol"]}` | {"0..1 optional" if f["optional"] else "1 required"} | 0..many | {f["delete"]} |')
md+=['','ON UPDATE is unspecified and restrictive for all FKs. Default ON DELETE RESTRICT is distinguished from explicit CASCADE / SET NULL above. Application deletion safeguards can be stricter.','']
for t in tables:
 md+=['## '+t['name'],'',notes[t['name']][1],'','| Column | SQL type | Nullable | Default / identity | Key |','|---|---|---|---|---|']
 for c in t['columns']: md.append(f'| `{c["name"]}` | `{c["type"]}` | {c["nullable"]} | `{c["default"]}` | {c["key"]} |')
 md+=['','Primary key: `('+', '.join(t['pk'])+')`.','', '```sql',*t['constraints'],'```','']
md+=['## Explicit secondary indexes','','| Name | Table | Ordered columns |','|---|---|---|']+[f'| `{i["name"]}` | `{i["table"]}` | `{i["columns"]}` |' for i in indexes]
md+=['','Primary and unique keys also create indexes. InnoDB creates missing FK supporting indexes. See page 14 of the PDF for expected names and prefix reuse.','',f'Totals: {len(tables)} tables; {count} columns; {len(fks)} FKs; {len(uniques)} UNIQUE constraints; {len(checks)} CHECK constraints; {len(indexes)} explicit secondary indexes.','']
(ROOT/'docs/DATABASE.md').write_text('\n'.join(md))
print(f'Generated {len(pages)} pages, {count} columns, {len(fks)} FKs, {len(checks)} checks, {len(indexes)} explicit indexes.')
